    $exact=['first_name'=>'first_name','firstname'=>'first_name','given_name'=>'first_name','last_name'=>'last_name','lastname'=>'last_name','surname'=>'last_name','full_name'=>'full_name','name'=>'full_name','email'=>'email','email_address'=>'email','work_email'=>'email','person_email'=>'email','company'=>'company_name','company_name'=>'company_name','organization'=>'company_name','organisation'=>'company_name','title'=>'job_title','job_title'=>'job_title','position'=>'job_title','role'=>'job_title','website'=>'website','web_site'=>'website','domain'=>'website','linkedin'=>'linkedin','linkedin_url'=>'linkedin','person_linkedin_url'=>'linkedin','facebook'=>'facebook','instagram'=>'instagram','twitter'=>'twitter','twitter_x'=>'twitter','x_url'=>'twitter','tiktok'=>'tiktok','phone'=>'phone','phone_number'=>'phone','mobile'=>'phone','cell'=>'phone','direct_phone'=>'phone','personal_phone'=>'phone','location'=>'location','city'=>'location','state'=>'location','region'=>'location','country'=>'country','source'=>'source','status'=>'status','notes'=>'notes','tags'=>'tags'];
